  6	function escapeHtml(str) {
  7	  if (str === null || str === undefined) return '';
  8	  return String(str)
  9	    .replace(/&/g, '&amp;')
 10	    .replace(/</g, '&lt;')
 11	    .replace(/>/g, '&gt;')
 12	    .replace(/"/g, '&quot;');
 13	}
 14	
 15	function formatDate(isoString) {
 16	  if (!isoString) return '—';
 17	  try {
 18	    var d = new Date(isoString);
 19	    if (isNaN(d.getTime())) return escapeHtml(isoString);
 20	    var pad = function (n) { return String(n).padStart(2, '0'); };
 21	    var timeStr = pad(d.getHours()) + ':' + pad(d.getMinutes());
 22	
 23	    var now = new Date();
 24	    // Strip times for day-boundary comparisons
 25	    var today    = new Date(now.getFullYear(),    now.getMonth(),    now.getDate());
 26	    var itemDay  = new Date(d.getFullYear(),      d.getMonth(),      d.getDate());
 27	    var diffDays = Math.round((today - itemDay) / 86400000);
 28	
 29	    if (diffDays === 0) return 'Today, ' + timeStr;
 30	    if (diffDays === 1) return 'Yesterday, ' + timeStr;
 31	    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
 32	    if (diffDays < 7)  return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][d.getDay()] + ', ' + d.getDate() + ' ' + months[d.getMonth()] + ', ' + timeStr;
 33	
 34	    // Older: show short date like "12 Feb 2026, 16:41"
 35	    return d.getDate() + ' ' + months[d.getMonth()] + ' ' + d.getFullYear() + ', ' + timeStr;
 36	  } catch (_) {
 37	    return escapeHtml(isoString);
 38	  }
 39	}
 40	
 41	function statusBadge(status) {
 42	  if (!status) return '';
 43	  var cls = 'badge badge-' + status.toLowerCase().replace(/_/g, '-');
 44	  return '<span class="' + cls + '">' + escapeHtml(status) + '</span>';
 45	}
 46	
 47	// Cache of namespaced key → display name, populated by views that fetch project data.
 48	// breadcrumb().project() reads from here automatically.
 49	// The cache key is the composite `repo + '/' + slug` to prevent collisions
 50	// between same-slug projects in different repositories.
 51	// Bounded to MAX_SIZE entries; oldest entries are evicted when the cap is exceeded.
 52	var ProjectNameCache = (function () {
 53	  var MAX_SIZE = 200;
 54	  var _cache = {};
 55	  var _keys = []; // insertion-order tracker for eviction (no duplicates)
 56	
 57	  return {
 58	    /**
 59	     * Store a display name for a project.
 60	     * @param {string} key  - Namespaced key in the form `repo/slug`.
 61	     *   Legacy callers that have not yet been migrated to the namespaced form (e.g.
 62	     *   `project-detail.js` — see WP-013) may pass a bare slug. Those entries will
 63	     *   not be found by namespaced `get()` calls until the caller is migrated.
 64	     * @param {string} name - Display name to cache.
 65	     */
 66	    set: function (key, name) {
 67	      if (!key || !name || !name.trim()) return;
 68	      var trimmed = name.trim();
 69	      // Update the value; only add to order tracker if this is a new key.
 70	      // NOTE: This is FIFO eviction, not LRU. Updating an existing key refreshes
 71	      // its value but does NOT move it to the back of the eviction queue — the key
 72	      // retains its original insertion position. For this cache (display names for
 73	      // up to 200 projects, rarely refreshed), FIFO is correct and sufficient.
 74	      if (!Object.prototype.hasOwnProperty.call(_cache, key)) {
 75	        _keys.push(key);
 76	        // Evict oldest entry if cap exceeded.
 77	        if (_keys.length > MAX_SIZE) {
 78	          var oldest = _keys.shift();
 79	          delete _cache[oldest];
 80	        }
 81	      }
 82	      _cache[key] = trimmed;
 83	    },
 84	    /**
 85	     * Retrieve the display name for a project.
 86	     * @param {string} key - Namespaced key in the form `repo/slug`.
 87	     *   Falsy values (null, undefined, empty string) are handled gracefully: a null/undefined
 88	     *   key returns null without throwing; an empty string key falls through to the slug
 89	     *   extraction path and returns an empty string.
 90	     * @returns {string|null} Cached display name, or the slug portion of the key (after the
 91	     *   last '/') if not found — so breadcrumbs show a readable label before project data is
 92	     *   fetched. Returns null for null/undefined input.
 93	     */
 94	    get: function (key) {
 95	      if (_cache[key]) return _cache[key];
 96	      // Fall back to the slug portion (after the last '/') so breadcrumbs show
 97	      // a readable label even before the project data is fetched.
 98	      var lastSlash = key ? key.lastIndexOf('/') : -1;
 99	      return lastSlash >= 0 ? key.slice(lastSlash + 1) : key;
100	    },
101	    /**
102	     * Returns the current number of cached entries.
103	     * Intended for testing; not part of the public API.
104	     */
105	    _size: function () {
106	      return _keys.length;
107	    },
108	  };
109	}());
110	
111	function breadcrumb() {
112	  var segments = [];
113	  var api = {
114	    projects: function () {
115	      segments.push({ label: 'Projects', href: '#/' });
116	      return api;
117	    },
118	    project: function (repo, slug) {
119	      segments.push({ label: ProjectNameCache.get(repo + '/' + slug), href: '#/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) });
120	      return api;
121	    },
122	    leaf: function (label) {
123	      segments.push({ label: label });
124	      return api;
125	    },
126	    leafSpan: function (label, id) {
127	      segments.push({ label: label, id: id });
128	      return api;
129	    },
130	    html: function () {
131	      return '<p class="breadcrumb">' +
132	        segments.map(function (s) {
133	          if (s.href) return '<a href="' + s.href + '">' + escapeHtml(s.label) + '</a>';
134	          if (s.id)   return '<span id="' + escapeHtml(s.id) + '">' + escapeHtml(s.label) + '</span>';
135	          return escapeHtml(s.label);
136	        }).join(' / ') +
137	        '</p>';
138	    }
139	  };
140	  return api;
141	}
142	
143	function showLoading(container) {
144	  container.innerHTML = '<div class="loading">Loading…</div>';
145	}
146	
147	function showError(container, message) {
148	  container.innerHTML = '<div class="error-banner">' + escapeHtml(message) + '</div>';
149	}

